import os,re
def strip_comments(src):
    out=[];depth=0;i=0;n=len(src)
    res=[]
    while i<n:
        if depth==0 and src.startswith('--',i):
            j=src.find('\n',i)
            if j<0: j=n
            res.append(' '*(j-i)); i=j
        elif src.startswith('/-',i):
            depth+=1; res.append('  '); i+=2
        elif src.startswith('-/',i) and depth>0:
            depth-=1; res.append('  '); i+=2
        elif depth>0:
            res.append(' ' if src[i]!='\n' else '\n'); i+=1
        else:
            res.append(src[i]); i+=1
    return ''.join(res)
